public class SecureDatabaseQuery {
    // Este método corrige a vulnerabilidade usando PreparedStatement,
    // que separa a lógica da consulta dos dados, prevenindo SQL Injection.
    public void buscarUsuario(String nomeUsuario) {
        String url = "jdbc:mysql://localhost:3306/meu_banco";
        String usuario = "root";
        String senha = "senha";

        // Boa prática: nunca concatene entradas do usuário em consultas SQL
        try (Connection conn = DriverManager.getConnection(url, usuario, senha);
             PreparedStatement pstmt = conn.prepareStatement("SELECT * FROM usuarios WHERE nome = ?")) {

            // Correção: define o parâmetro de forma segura
            pstmt.setString(1, nomeUsuario);

            ResultSet rs = pstmt.executeQuery();

            // Processar resultados...
